def read_rows(sheet_xml, shared):
    rows = []
    for r in sheet_xml.findall('.//a:row', NS):
        vals = []
        for c in r.findall('a:c', NS):
            v = c.find('a:v', NS)
            val = v.text if v is not None else ''
            if c.get('t') == 's' and val:
                val = shared[int(val)]
            vals.append(val)
        rows.append(vals)  # later: dict(zip(header, vals))
    return rows
